cases.sql:
SELECT id, plan, customer_id, monthly_fee
FROM subscriptions
WHERE monthly_fee BETWEEN (SELECT MIN(amount) FROM payments) AND (SELECT AVG(amount) FROM payments);

SELECT id, order_date, status, discount
FROM orders
WHERE discount = (SELECT MAX(discount) FROM orders WHERE channel IN ('partner', 'web'));

SELECT id, units
FROM store_sales
WHERE units < (SELECT AVG(units) FROM store_sales WHERE units <= 20);

SELECT id, age
FROM customers
WHERE age < (SELECT AVG(age) FROM customers);

select id, duration_sec
from web_events
where duration_sec > 0.5 * (select avg(duration_sec) from web_events);

SELECT id, customer_id, amount, discount
FROM orders
WHERE discount >= 1.2 * (SELECT AVG(discount) FROM orders WHERE discount > 0.2);

SELECT id, customer_id, monthly_fee
FROM subscriptions
WHERE monthly_fee BETWEEN (SELECT MIN(monthly_fee) FROM subscriptions) AND (SELECT AVG(monthly_fee) FROM subscriptions);

SELECT id, paid_at, amount, amount - (SELECT AVG(amount) FROM orders) AS amount_vs_avg
FROM payments
ORDER BY paid_at;

SELECT id, salary
FROM employees
WHERE salary < 1.5 * (SELECT AVG(salary) FROM employees WHERE job_title IN ('Director', 'Manager'));

SELECT id, supplier_name, country, rating, ROUND(rating * 100.0 / (SELECT SUM(rating) FROM suppliers), 2) AS share_pct
FROM suppliers
WHERE city <> 'Tokyo';

select id, store_id, units
from store_sales
where units between (select min(units) from store_sales where sale_date < '2024-07-09') and (select avg(units) from store_sales where revenue <= 2182);
